body.script:

var cart = {};
var currency = document.body.getAttribute('data-currency') || '';
function esc(t) { var d = document.createElement('div'); d.textContent = t; return d.innerHTML; }
var configId = document.body.getAttribute('data-config-id');
var tableIdRaw = document.body.getAttribute('data-table-id');
var tableId = tableIdRaw ? parseInt(tableIdRaw, 10) : null;

document.getElementById('categTabs').addEventListener('click', function(ev){
    if (!ev.target.classList.contains('categ-tab')) return;
    document.querySelectorAll('.categ-tab').forEach(function(b){ b.classList.remove('active'); });
    ev.target.classList.add('active');
    var categId = ev.target.getAttribute('data-categ');
    document.querySelectorAll('.card').forEach(function(c){
        c.style.display = (c.getAttribute('data-categ') === categId) ? '' : 'none';
    });
});

document.getElementById('productGrid').addEventListener('click', function(ev){
    var card = ev.target.closest('.card');
    if (!card) return;
    if (document.body.getAttribute('data-menu-only')) return;
    var id = card.getAttribute('data-id');
    if (!cart[id]) {
        cart[id] = { id: id, name: card.getAttribute('data-name'),
                     price: parseFloat(card.getAttribute('data-price')), qty: 0 };
    }
    cart[id].qty += 1;
    renderCart();
});

function changeQty(id, delta) {
    if (!cart[id]) return;
    cart[id].qty += delta;
    if (cart[id].qty <= 0) delete cart[id];
    renderCart();
}

function renderCart() {
    var ids = Object.keys(cart);
    var linesEl = document.getElementById('cartLines');
    var total = 0, count = 0;
    if (!ids.length) {
        linesEl.innerHTML = '<div class="empty">Panier vide</div>';
    } else {
        linesEl.innerHTML = '';
        ids.forEach(function(id){
            var item = cart[id];
            total += item.price * item.qty;
            count += item.qty;
            var row = document.createElement('div');
            row.className = 'cart-line';
            row.innerHTML = '<span>' + esc(item.name) + '</span>' +
                '<span class="qty-ctrl">' +
                '<button onclick="changeQty(\'' + id + '\',-1)">-</button> ' +
                item.qty +
                ' <button onclick="changeQty(\'' + id + '\',1)">+</button></span>' +
                '<span>' + Math.round(item.price * item.qty) + ' ' + esc(currency) + '</span>';
            linesEl.appendChild(row);
        });
    }
    var bar = document.getElementById('cartBar');
    bar.style.display = count ? 'flex' : 'none';
    document.getElementById('cartCount').textContent = count + ' article(s)';
    document.getElementById('cartTotal').textContent = Math.round(total) + ' ' + currency;
}

function submitOrder() {
    var lines = Object.keys(cart).map(function(id){
        return { product_id: cart[id].id, qty: cart[id].qty };
    });
    if (!lines.length) { alert('Votre panier est vide.'); return; }
    fetch('/adk_pos/kiosk/' + configId + '/submit', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ jsonrpc: '2.0', method: 'call',
            params: { lines: lines, table_id: tableId,
                      customer_note: document.getElementById('customerNote').value } })
    }).then(function(r){ return r.json(); }).then(function(data){
        var result = data.result || {};
        if (result.error) { alert(result.error); return; }
        document.body.innerHTML = '<div style="text-align:center;padding:80px 20px;">' +
            '<h2>Commande envoyée !</h2><p>Référence : ' + result.order_name + '</p>' +
            '<p>Merci, votre commande a été transmise. Un membre de l\'équipe va la confirmer.</p></div>';
    }).catch(function(){ alert("Erreur réseau, merci de réessayer."); });
}

var url = document.body.getAttribute('data-url');
function esc(s){ var d=document.createElement('div'); d.textContent=s==null?'':s; return d.innerHTML; }
function render(d){
    var m = document.getElementById('main');
    if (d.state === 'order') {
        m.innerHTML = '<div class="lines">' + d.lines.map(function(l){
            return '<div class="line"><span>' + esc(l.qty) + ' × ' + esc(l.name) + '</span><strong>' + esc(l.total) + '</strong></div>'; }).join('') +
            '</div><div class="total"><div class="lbl">Total</div><div class="val">' + esc(d.total) + '</div></div>';
    } else if (d.state === 'paid') {
        m.innerHTML = '<div class="center">Merci et à bientôt !<small>Payé : ' + esc(d.total) + (d.change ? ' · Monnaie : ' + esc(d.change) : '') + '</small></div>';
    } else {
        m.innerHTML = '<div class="center">Bienvenue<small>' + esc(d.text || d.name) + '</small></div>';
    }
}
function tick(){
    fetch(url, {method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({jsonrpc:'2.0', method:'call', params:{}})})
      .then(function(r){return r.json();}).then(function(j){ if (j.result) render(j.result); }).catch(function(){});
}
tick(); setInterval(tick, 2000);
